'use strict';
const NBranch=VersionBranch;let navStack=[],navRestoring=false;
const routePage=()=>['creator','result','history','reviews','knowledge'].find(p=>$('#'+p+'-page')&&!$('#'+p+'-page').classList.contains('hidden'))||'creator';
function editorDirty(){return routePage()==='result'&&current?.owner===user()&&$('#output')&&($('#output').value!==current.content||($('#final-title')&&$('#final-title').value!==current.title));}
document.body.insertAdjacentHTML('beforeend','<dialog id="navigation-unsaved"><h2>有尚未保存的修改</h2><p>返回前请选择如何处理当前文案，取消将继续留在本页。</p><div class="button-row"><button id="nav-save-return" class="button primary">保存后返回</button><button id="nav-discard-return" class="button ghost">放弃修改并返回</button><button id="nav-cancel-return" class="button ghost">取消</button></div><p id="nav-save-error" role="alert"></p></dialog><dialog id="version-branch-dialog"><h2 id="branch-heading"></h2><p id="branch-context" class="muted"></p><label class="field">该版标题<input id="branch-title"></label><label class="field">基于该版的正文<textarea id="branch-body" class="editable"></textarea></label><label class="field">本轮修改要求<textarea id="branch-instruction" placeholder="写清本轮需要调整什么"></textarea></label><p id="branch-error" class="field-error" role="alert"></p><div class="button-row"><button id="branch-submit" class="button primary">提交修改，生成新版本</button><button id="branch-cancel" class="button ghost">返回查看版本</button></div></dialog>');
function guardNavigation(proceed){if(!editorDirty()){proceed();return;}$('#nav-save-error').textContent='';$('#navigation-unsaved').showModal();$('#nav-save-return').onclick=()=>{const saved=VersionSafety.clone(current);syncEdits(current);if(!persist()){Object.keys(current).forEach(k=>delete current[k]);Object.assign(current,saved);$('#nav-save-error').textContent='保存失败，当前编辑仍在页面，请备份后再返回。';return;}$('#navigation-unsaved').close();proceed();};$('#nav-discard-return').onclick=()=>{renderResult();$('#navigation-unsaved').close();proceed();};$('#nav-cancel-return').onclick=()=>$('#navigation-unsaved').close();}
const navShow=show;
function routeTo(p,restore=null){const from=routePage();if(p!==from&&!navRestoring)navStack.push({page:from,id:current?.id,scroll:window.scrollY,revision:$('#revision')?.value||''});if(restore?.id&&p==='result'){const r=db.records.find(x=>x.id===restore.id&&x.business===business()&&(admin()||x.owner===user()));if(r)current=r;else p='creator';}navShow(p);if(p==='result'&&restore&&current){renderResult();if($('#revision'))$('#revision').value=restore.revision||'';}addBackButton(p);if(restore)requestAnimationFrame(()=>window.scrollTo(0,restore.scroll||0));}
show=function(p){if(p===routePage()){navShow(p);addBackButton(p);return;}if(!busy&&!navRestoring)guardNavigation(()=>routeTo(p));else routeTo(p);};
function backPage(){if(busy||feedbackPending)return;guardNavigation(()=>{const target=navStack.pop()||{page:'creator',scroll:0};navRestoring=true;try{routeTo(target.page,target);}finally{navRestoring=false;}});}
function addBackButton(p=routePage()){if(p==='creator'||$('#'+p+'-page #page-back'))return;const page=$('#'+p+'-page');if(!page||page.classList.contains('hidden'))return;page.insertAdjacentHTML('afterbegin','<div class="button-row page-back-row"><button id="page-back" class="button ghost">返回上一步</button></div>');page.querySelector('#page-back').onclick=backPage;}
const navRenderResult=renderResult;
renderResult=function(){navRenderResult();if(!current)return;addBackButton('result');const based=current.versionLineage?.[current.version];if(based)$('#result-page .result-top').insertAdjacentHTML('afterend','<p class="feedback-terminal">第 '+current.version+' 版 · 基于第 '+based.basedOnVersion+' 版修改；原历史版本保留。</p>');if(current.owner===user()){$$('#result-page .revise details.issue').filter(el=>el.querySelector('.review-body')).forEach(el=>{const match=el.querySelector('summary')?.textContent.match(/第 (\d+) 版/);if(!match)return;const version=Number(match[1]);el.insertAdjacentHTML('beforeend','<button class="button ghost" data-branch-version="'+version+'">基于此版本继续修改</button>');});$$('[data-branch-version]').forEach(b=>b.onclick=()=>guardNavigation(()=>openVersionBranch(Number(b.dataset.branchVersion))));}};
function openVersionBranch(version){try{const record=current,draft=NBranch.prepare(record,version,user(),business());$('#branch-heading').textContent='基于第 '+version+' 版继续修改';$('#branch-context').textContent='当前最新第 '+record.version+' 版；提交成功后生成第 '+(record.version+1)+' 版，不覆盖任何旧版。'+(draft.legacySettings?'旧快照部分设置未记录，将沿用该任务现有设置；缺少来源时重新检索，不冒称已保留完整旧设置。':'沿用该版已记录的要求、保留项与来源。');$('#branch-title').value=draft.title;$('#branch-body').value=draft.content;$('#branch-instruction').value='';$('#branch-error').textContent='';$('#version-branch-dialog').showModal();$('#branch-submit').onclick=async()=>{const instruction=$('#branch-instruction').value.trim(),text=$('#branch-body').value.trim(),title=$('#branch-title').value.trim();if(!instruction||!text||!title){$('#branch-error').textContent='请填写标题、正文和本轮修改要求。';return;}if(record.owner!==user()||record.business!==business()){$('#branch-error').textContent='当前身份或业务已变化，请重新打开版本。';return;}const beforeVersion=record.version,liked=record.liked;const input={business:record.business,inputType:draft.inputType,operation:'rewrite',material:text,requirements:draft.requirements,retain:draft.retain,outputType:draft.outputType,revision:instruction,parentSources:draft.sources.length?draft.sources:undefined,scenario:'available',branchBaseVersion:version,branchTitle:title};$('#version-branch-dialog').close();await run(input,record);};}catch(e){notify(e.message);}}
$('#branch-cancel').onclick=()=>$('#version-branch-dialog').close();
const branchRun=run;
run=async function(input,parent=null){const before=parent?.version,liked=parent?.liked;await branchRun(input,parent);if(input.branchBaseVersion&&parent&&NBranch.stamp(parent,input.branchBaseVersion,before,liked)){Object.assign(parent,{title:input.branchTitle||parent.title,requirements:input.requirements||'',retain:input.retain||'',outputType:input.outputType||parent.outputType});const saved=persist();renderResult();$('#result-page .result-top').insertAdjacentHTML('afterend','<p id="task-terminal" class="feedback-terminal" role="status">'+(saved?'修改完成，新版本已保存到本地历史。':'修改已完成，但本地保存失败，请先下载备份。')+'</p>');}addBackButton('result');};
const navDirections=renderDirections;
renderDirections=function(r){navDirections(r);$('#directions-box').insertAdjacentHTML('afterbegin','<button id="back-to-assessment" class="button ghost">返回评估报告</button>');$('#back-to-assessment').onclick=()=>{$('#directions-box').innerHTML='';};};
const navOpenSource=openSource;
openSource=function(s){navOpenSource(s);if($('#review-dialog').open)$('#close-dialog').textContent='返回上一页面';};
const navOpenReview=openReview;openReview=function(x){$('#close-dialog').textContent='关闭';navOpenReview(x);};
for(const selector of ['#business','#identity']){const previous=$(selector).onchange;$(selector).onchange=()=>{navStack=[];previous();};}
